def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers = list(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    dist = instance["distance_matrix"]

    def route_load(route):
        s = 0
        for c in route:
            s += demands[c]
        return s

    def route_cost(route):
        if not route:
            return 0
        c = dist[depot][route[0]]
        for i in range(len(route) - 1):
            c += dist[route[i]][route[i + 1]]
        c += dist[route[-1]][depot]
        return c

    def insertion_delta(route, pos, node):
        prev = depot if pos == 0 else route[pos - 1]
        nxt = depot if pos == len(route) else route[pos]
        return dist[prev][node] + dist[node][nxt] - dist[prev][nxt]

    def best_insertion(route, node):
        best_pos = 0
        best_delta = None
        for pos in range(len(route) + 1):
            d = insertion_delta(route, pos, node)
            if best_delta is None or d < best_delta or (d == best_delta and pos < best_pos):
                best_delta = d
                best_pos = pos
        return best_pos, best_delta

    def two_opt(route):
        n = len(route)
        if n < 3:
            return route
        improved = True
        while improved:
            improved = False
            best_delta = 0
            bi = bj = -1
            for i in range(n - 1):
                a = depot if i == 0 else route[i - 1]
                b = route[i]
                for j in range(i + 1, n):
                    c = route[j]
                    d = depot if j == n - 1 else route[j + 1]
                    delta = dist[a][c] + dist[b][d] - dist[a][b] - dist[c][d]
                    if delta < best_delta or (delta == best_delta and (i < bi or (i == bi and j < bj))):
                        best_delta = delta
                        bi = i
                        bj = j
            if best_delta < 0:
                route = route[:bi] + route[bi:bj + 1][::-1] + route[bj + 1:]
                n = len(route)
                improved = True
        return route

    def normalize_routes(routes):
        out = []
        for r in routes:
            if r:
                out.append(r)
        out.sort(key=lambda r: (r[0], len(r), tuple(r)))
        return out

    def route_signature(route):
        return tuple(route)

    def improve_route(route):
        route = two_opt(route)
        changed = True
        while changed:
            changed = False
            n = len(route)
            best_delta = 0
            best_move = None
            for i in range(n):
                node = route[i]
                prev = depot if i == 0 else route[i - 1]
                nxt = depot if i == n - 1 else route[i + 1]
                remove_delta = dist[prev][nxt] - dist[prev][node] - dist[node][nxt]
                for j in range(n + 1):
                    if j == i or j == i + 1:
                        continue
                    prev2 = depot if j == 0 else route[j - 1] if j < i else route[j - 2]
                    nxt2 = depot if j == n or (j == i + 1 and i == n - 1) else route[j] if j < i else route[j - 1]
                    if j > i:
                        # after removing i, positions shift left
                        prev2 = depot if j == 0 else route[j - 1]
                        nxt2 = depot if j == n else route[j] if j < n else depot
                        # insert into reduced route at position j-1
                        prev2 = depot if j - 1 == 0 else route[j - 2] if j - 1 > 0 else depot
                        nxt2 = depot if j - 1 == n - 1 else route[j - 1] if j - 1 < n - 1 else depot
                    else:
                        prev2 = depot if j == 0 else route[j - 1]
                        nxt2 = depot if j == n - 1 else route[j]
                    if j > i:
